using namespace std;

void fibonacci(int n, int a, int b, vector<int>& sequence) {
    if (n <= 0) {
        cout << "Invalid input. Please enter a positive integer for the number of sequence elements." << endl;
        return;
    }

    if (cin.fail() || cin.peek() != ',' || cin.peek() != ' ') {
        cout << "Invalid input. Please enter two integers separated by a comma and a space." << endl;
        return;
    }

    cin.ignore(1); // consume comma
    cin.ignore(1); // consume space

    if (!cin) {
        cout << "Error reading input." << endl;
        return;
    }

    sequence.push_back(a);
    sequence.push_back(b);

    if (n <= 2) {
        return;
    }

    fibonacci(n - 1, b, a + b, sequence);
}

int main() {
    int numElements;
    int firstNumber, secondNumber;
    vector<int> sequence;

    cout << "Enter the first two numbers in the Fibonacci sequence, separated by a comma and a space: ";
    cin >> firstNumber >> secondNumber;

    if (cin.fail() || cin.peek() != ',') {
        cout << "Invalid input. Please enter two integers separated by a comma and a space." << endl;
        return 1;
    }

    cin.ignore();
    cin >> numElements;

    fibonacci(numElements, firstNumber, secondNumber, sequence);

    cout << "Fibonacci sequence of length " << numElements << ": ";
    for (auto elem : sequence) {
        cout << elem << ",";
    }
    cout << "\b"; // remove last comma

    return 0;
}
```

