function determineProtocol(inputData) {
  const ipv6Regex = /^([0-9a-f:]{1,32})$/i; // Regular expression to match IPv6 addresses
  const sourceIPv6 = ipv6Regex.test(inputData.sourceIP);
  const destinationIPv6 = ipv6Regex.test(inputData.destinationIP);
  let protocol = null;

  if (sourceIPv6 && destinationIPv6) {
    if (inputData.port === 80) {
      protocol = "HTTP";
    } else {
      protocol = "UDP";
    }
  }

  return protocol || "Unknown";
