First, create a new folder named `guards` inside the `src/auth` directory. Inside the `guards` folder, create two files: `jwt-auth.guard.ts` and `roles.guard.ts`.

Now, let's write the JWT authentication guard (`jwt-auth.guard.ts`):

```typescript
import { Injectable } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';

@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {}
```

Next, create the roles guard (`roles.guard.ts`):

```typescript
import { Injectable, CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { Role } from 'src/user/user.entity'; // Assuming User entity has Role property

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const roles = this.reflector.get<Role[]>('roles', context.getHandler());
    if (!roles) return true;

    const request = context.switchToHttp().getRequest();
    const user = request.user;

    if (!user || !roles.some((role) => role === user.role)) {
      throw new UnauthorizedException();
    }

    return true;
  }
}
```

Finally, update your main application module file (usually `app.module.ts`) to import and register these guards:

