```csharp
using System;
using System.IdentityModel.Tokens.Jwt;

public static string GetUsernameFromJwt(string jwtToken)
{
    try
    {
        // Handler for JWT tokens
        JwtSecurityTokenHandler tokenHandler = new JwtSecurityTokenHandler();

        // Parse the token
        JwtSecurityToken jwtTokenObject = tokenHandler.ReadJwt(jwtToken);

        // Return the username claim
        return jwtTokenObject.Claims.FirstOrDefault(x => x.Type == "sub")?.Value;
    }
    catch (Exception ex)
    {
        throw new ArgumentException("Invalid or expired JWT token", nameof(jwtToken));
    }
}
```

