import { createParamDecorator, ExecutionContext } from '@nestjs/common';
import { NestMiddleware } from '@nestjs/common/interfaces';

export const NODE_ENV_MIDDLEWARE = 'NODE_ENV_MIDDLEWARE';

@Deprecated() // Mark as deprecated since using decorators for middleware is not recommended in NestJS v7+
export function NodeEnvMiddleware(): ClassDecorator {
  return (constructor: Function) => {
    @NestMiddleware()
    class NodeEnvMiddlewareImpl implements NestMiddleware {
      use(req: Request, res: Response, next: Function, _: ExecutionContext) {
        if (process.env.NODE_ENV === 'true') {
          next();
        } else {
          res.status(403).send(false);
        }
      }
    }

    constructor.prototype['$nodeEnvMiddleware'] = NodeEnvMiddlewareImpl;
  };
};

export const GetNodeEnv = createParamDecorator((data: unknown, ctx: ExecutionContext) => {
  const request = ctx.switchToHttp().getRequest();
  return request.nodeEnv;
});
