 To create a simple toast notification using React and the useContext Hook, follow these steps: First, let's create a custom ToastContext provider and its component.

1. Create a new file named `ToastContext.js`:

```javascript
import { createContext, useState } from "react";

export const ToastContext = createContext();

export const ToastProvider = ({ children }) => {
  const [message, setMessage] = useState(null);

  const addToast = (message) => {
    setMessage(message);
    setTimeout(() => setMessage(null), 3000); // clear message after 3 seconds
  };

  return (
    <ToastContext.Provider value={{ addToast }}>
      {children}
      {message && <Toast key="toast" className="toast">{message}</Toast>}
    </ToastContext.Provider>
  );
};
```

2. In your main App component or wherever you want to use the ToastContext, wrap it around your children components:

```javascript
import React from "react";
import { ToastContext, ToastProvider } from "./ToastContext";
import ChildComponent from "./ChildComponent";

function App() {
  return (
    <ToastProvider>
      <ToastContext.Consumer>
        {({ addToast }) => (
          <div className="App">
            <button onClick={() => addToast("This is a test toast!")}>
              Show Toast
            </button>
            <ChildComponent />
          </div>
        )}
      </ToastContext.Consumer>
    </ToastProvider>
  );
}

export default App;
```

3. Create a new file named `ChildComponent.js`:

```javascript
import React from "react";
import { useContext } from "react";
import { ToastContext } from "../ToastContext";

function ChildComponent() {
  const { addToast } = useContext(ToastContext);

