def num_to_words(num):
    if num < 0:
        return "minus " + num_to_words(-num)

    def num_to_words_helper(num):
        if num < 20:
            return ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"][num]
        elif num < 100:
            return num_to_words_helper(num // 10) + " " + num_to_words_helper(num % 10)
        elif num < 1000:
            return num_to_words_helper(num // 100) + " hundred " + num_to_words_helper(num % 100)
        elif num < 1_000_000:
            return num_to_words_helper(num // 1000) + " thousand " + num_to_words_helper(num % 1000)
        else:
            raise ValueError("Number too big")

    return num_to_words_helper(num)
```

