 Here's an example implementation of the `RedisClient` class in Node.js using the `redis` package:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('error', (err) => console.error(`Error connecting to Redis: ${err}`));
  }

  isAlive() {
    return this.client.connected;
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, value) => {
        if (err) {
          reject(err);
        } else {
          resolve(value);
        }
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply);
        }
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, result) => {
        if (err) {
          reject(err);
        } else {
          resolve(result);
        }
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

This implementation defines the `RedisClient` class with the required functions and exports an instance of the class named `redisClient`. The constructor initializes a new Redis client and sets up an error handler. Each function defined in the class is asynchronous and uses Promises to handle the results or errors from the Redis client methods. The `isAlive` method checks if the client is connected to Redis.

