 To identify if a given sentence in Go contains a double negative, follow these steps:

1. Define a slice of specific negative words.
2. Split the input sentence into words using spaces as delimiters.
3. Iterate through each word in the sliced sentence.
4. Check if the current word is in the negative words slice or if the word before it is "not" and the current word is also a negative word.
5. If either condition is true, increment a counter.
6. After iterating through all the words, if the counter has a value greater than zero, print a message indicating that the sentence contains a double negative.

Here's the Go code implementing the above logic:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	negativeWords := []string{"isn't", "am not", "aren't", "doesn't", "don't", "haven't", "hasn't", "hadn't", "won't", "wouldn't", "can't", "couldn't", "shall not", "shouldn't", "may not", "might not", "must not"}
	sentence := "He isn't not worried about the coronavirus situation"
	words := strings.Split(sentence, " ")
	counter := 0

	for i := 0; i < len(words)-1; i++ {
		if contains(negativeWords, words[i]) || (i < len(words)-1 && words[i] == "not" && contains(negativeWords, words[i+1])) {
			counter++
		}
	}

	if counter > 0 {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}

func contains(slice []string, item string) bool {
	for _, a := range slice {
		if a == item {
			return true
		}
	}
	return false
}
```

